  "type": "科学家",
  "life": "1919—2006",
  "role": "自动控制专家、两弹一星元勋",
  "story": "江苏吴江人。中国科学院院士。我国卫星自动控制技术的开拓者之一，为'东方红一号'等卫星的姿态控制提供了关键技术。1999年获'两弹一星'功勋奖章。",
  "quote": "为了祖国的航天事业，我愿做一名铺路石。",
