  "story": "山西文水县云周西村人。1945年参加革命工作，任村妇救会秘书，1946年6月被批准为中国共产党候补党员，年仅14岁。她组织群众支前、掩护干部，配合武工队打击敌人。1947年1月12日，国民党军突袭云周西村，她因叛徒出卖被捕。面对利诱与铡刀，她坚贞不屈，从容就义，年仅15岁。毛泽东为她题词：\"生的伟大，死的光荣。\"",
  "quote": "怕死不当共产党。",
