  "story": "四川自贡人，人们熟知的\"江姐\"。1947年她负责中共重庆市委地下刊物《挺进报》的组织发行，后赴川东参与武装斗争。1948年6月在万县被捕，关押于重庆渣滓洞监狱。面对竹签钉入指尖等酷刑，她始终没有吐露党的秘密，并在狱中鼓励难友坚持斗争。1949年11月14日，重庆解放前夕，她在歌乐山电台岚垭刑场英勇就义，年仅29岁。",
  "quote": "竹签子是竹子做的，共产党员的意志是钢铁。",
