  "role": "中国人民志愿军特级英雄",
  "story": "四川中江人。1951年参加中国人民志愿军，任第15军45师135团2营通信员。1952年10月，上甘岭战役中，部队进攻597.9高地受阻于敌军中心火力点，连续爆破未果、身边战友伤亡殆尽。他主动请求执行爆破任务，弹药用尽、身负重伤后，毅然用胸膛堵住敌人正在喷射火舌的机枪射孔，为部队开辟了胜利的道路，壮烈牺牲，年仅21岁。志愿军机关为他追记特等功、追授\"特级英雄\"称号。",
