  "story": "四川铜梁人。1951年参加中国人民志愿军，任第15军29师87团9连战士。1952年10月12日，他随部队在391高地敌军阵地前沿潜伏。敌军盲目发射的燃烧弹落在他身边，烈火迅速烧着了他的棉衣、头发和皮肉。为了不暴露潜伏部队、保证整个作战计划的完成，他强忍烈火烧身的剧痛，双手深深插进泥土，始终一动不动，直至壮烈牺牲，年仅26岁。部队为他追记特等功、追授\"一级英雄\"称号。",
