  "life": "1940—1962",
  "role": "全军挂像英模",
  "story": "湖南望城人。中国人民解放军沈阳军区工程兵某部运输连战士。他以全心全意为人民服务为宗旨，在平凡的岗位上做出了不平凡的事迹。1962年8月15日因公殉职，年仅22岁。1963年毛泽东题词'向雷锋同志学习'，雷锋精神影响了一代又一代中国人。",
  "quote": "人的生命是有限的，可是为人民服务是无限的，我要把有限的生命投入到无限的为人民服务之中去。",
