  "role": "国际主义战士",
  "story": "加拿大人。著名胸外科医师。1938年率加美援华医疗队来到中国，在晋察冀抗日前线救治伤员。他手术救治了大批八路军伤员，培养了许多战地医务人员。1939年11月12日，因在手术中被划破手指感染败血症，不幸逝世。毛泽东写下《纪念白求恩》。",
  "quote": "我唯一的希望是能够多做贡献。",
