  "story": "山东临清人。国民革命军陆军第三十三集团军总司令。他是抗战中同盟国牺牲的最高级别将领之一。1940年5月，在枣宜会战中，他亲率部队与日军激战，身中数弹仍坚持指挥，5月16日壮烈殉国，时年49岁。他的遗体被日军以军礼致敬，后运回重庆，国民政府为其举行国葬。",
  "quote": "我生国死，我死国生。",
